FILE = "01-01-goal-decisions-aqs.vi.md"
PAIRS = [
("""**Mục tiêu và chỉ số đo.** Business Goal (mục tiêu của tổ chức) của dự án là nâng tỷ lệ hoàn thành học phần""",
 """**Mục tiêu và chỉ số đo.** Mục tiêu của tổ chức (Business Goal) là nâng tỷ lệ hoàn thành học phần"""),
("""SMART Goal (mục tiêu cụ thể, đo lường được, khả thi, phù hợp và có thời hạn) đặt mục tiêu này thành một mức cụ thể.""",
 """Mục tiêu SMART (SMART Goal), tức mục tiêu cụ thể, đo lường được, khả thi, phù hợp và có thời hạn, chuyển mục tiêu này thành một mức cần đạt."""),
("""Bên cạnh đó, hai KPI phụ theo dõi hoạt động liên hệ: tỷ lệ sinh viên có dấu hiệu sớm của việc giảm tham gia học tập được liên hệ tính đến hết tuần 5 và tỷ lệ sinh viên có tên trong danh sách liên hệ được liên hệ trong vòng bảy ngày.""",
 """Bên cạnh đó, hai KPI phụ theo dõi hoạt động liên hệ. KPI phụ thứ nhất xét các sinh viên có dấu hiệu sớm của việc giảm tham gia học tập và đo tỷ lệ sinh viên trong nhóm này được liên hệ tính đến hết tuần 5. KPI phụ thứ hai xét các sinh viên có tên trong danh sách liên hệ và đo tỷ lệ sinh viên được liên hệ trong vòng bảy ngày."""),
("""Quyết định D1 là giảng viên kiêm cố vấn học tập và phòng hỗ trợ sinh viên liên hệ với những ai ở mỗi đợt lập danh sách, tức thời điểm vào tuần 3 và tuần 5 khi danh sách liên hệ được chuyển đến cán bộ.""",
 """Quyết định D1 xác định những sinh viên mà giảng viên kiêm cố vấn học tập và phòng hỗ trợ sinh viên sẽ liên hệ ở mỗi đợt lập danh sách. Đợt lập danh sách là thời điểm vào tuần 3 và tuần 5 khi danh sách liên hệ được chuyển đến cán bộ."""),
("""Quyết định D2 là Trưởng chương trình đào tạo phân bổ thời gian của phòng hỗ trợ sinh viên và của giảng viên kiêm cố vấn học tập vào đâu trong mỗi học kỳ; quyết định D3 là có mở rộng cách làm này cho mọi học phần sau đợt thí điểm hay không.""",
 """Quyết định D2 xác định cách Trưởng chương trình đào tạo phân bổ thời gian của phòng hỗ trợ sinh viên và của giảng viên kiêm cố vấn học tập trong mỗi học kỳ. Quyết định D3 xác định có mở rộng cách làm này cho mọi học phần sau đợt thí điểm hay không."""),
("""Module là một học phần của OU; các module mang mã đã ẩn danh từ AAA đến GGG; mỗi lần tổ chức một module, gọi là kỳ mở module, được đặt tên theo năm và tháng bắt đầu: B là tháng 2, J là tháng 10 [2].""",
 """Module là một học phần của OU, và các module mang mã đã ẩn danh từ AAA đến GGG. Mỗi lần một module được tổ chức là một kỳ mở module (module run); kỳ mở được đặt tên theo năm và tháng bắt đầu, với B là tháng 2 và J là tháng 10 [2]."""),
("""Ngoài ra, các thay đổi này thay việc so sánh theo hình thức học và năm theo học bằng so sánh theo module và kỳ mở, đồng thời điều chỉnh cách đo của hai câu hỏi như trình bày dưới đây.""",
 """Ngoài ra, các thay đổi này bỏ phép so sánh theo hình thức học (trực tuyến hoặc kết hợp) và theo năm học của sinh viên, thay bằng phép so sánh theo module và theo kỳ mở. Đồng thời, các thay đổi này điều chỉnh cách đo của hai câu hỏi như trình bày dưới đây."""),
("""Theo đề bài, nhóm tác giả chỉ được mô hình hóa những câu hỏi phân tích (AQ) vẫn còn hiệu lực sau bước đánh giá mức phù hợp giữa AQ và dữ liệu (AQ–Data Fit) ở Milestone 3, bước đối chiếu từng câu hỏi với dữ liệu thực; phần nào đã hoãn chỉ được đưa trở lại khi có thay đổi được ghi vào Nhật ký thay đổi [1].""",
 """Theo đề bài, nhóm tác giả chỉ được mô hình hóa những câu hỏi phân tích (AQ) vẫn còn hiệu lực sau bước đánh giá mức phù hợp giữa AQ và dữ liệu (AQ–Data Fit) ở Milestone 3. Bước này đối chiếu từng câu hỏi với dữ liệu thực. Nếu một phần của câu hỏi đã bị hoãn, phần đó chỉ được đưa trở lại khi có một thay đổi được ghi vào Nhật ký thay đổi [1]."""),
("""Sẵn sàng ở dạng xếp hạng; việc chọn cách liên hệ được hoãn đến đợt thí điểm (C11)""",
 """Sẵn sàng ở dạng xếp hạng; việc chọn hình thức liên hệ được hoãn đến đợt thí điểm (C11)"""),
("""Thứ hai, một danh sách được đánh giá bằng tỷ lệ phát hiện, tức tỷ lệ sinh viên về sau không hoàn thành có tên trong danh sách, so với mức tối đa mà một danh sách cùng độ dài có thể đạt. Danh sách đó cũng được đánh giá bằng mức vượt tỷ lệ nền của kỳ mở (lift), trong đó tỷ lệ nền là tỷ lệ sinh viên không hoàn thành, vì một danh sách ngẫu nhiên đã đạt sẵn tỷ lệ này (C13).""",
 """Thứ hai, một danh sách được đánh giá bằng hai chỉ số (C13). Chỉ số thứ nhất là tỷ lệ phát hiện: trong số sinh viên về sau không hoàn thành, bao nhiêu phần trăm có tên trong danh sách. Tỷ lệ này được so với mức tối đa mà một danh sách cùng độ dài có thể đạt. Chỉ số thứ hai so danh sách với tỷ lệ nền của kỳ mở, là tỷ lệ sinh viên không hoàn thành trong kỳ mở đó. Một danh sách chọn ngẫu nhiên cũng có tỷ lệ sinh viên không hoàn thành đúng bằng tỷ lệ nền, nên danh sách tốt phải vượt mức này; chỉ số thứ hai vì vậy gọi là mức vượt tỷ lệ nền (lift)."""),
]
